(()=>{
 const jointLabel=(f,j)=>f===0?handJointNames[j]:['벌림 X','MCP 굽힘','PIP 굽힘','DIP 굽힘'][j];
 const range=(f,j)=>f===0?[[-60,60],[-65,35],[0,75],[0,80]][j]:j===0?[-25,25]:[0,fingerLimits[j-1]];
 const slider=(f,j,prefix)=>{const [lo,hi]=range(f,j);return`<label>${jointLabel(f,j)}<output id="${prefix}-${f}-${j}-out"></output><input data-finger="${f}" data-joint="${j}" id="${prefix}-${f}-${j}" type="range" min="${lo}" max="${hi}" step=".1" value="${handState.q[f][j]}"></label>`;};
 $('all-hand-controls').innerHTML=digitNames.map((name,f)=>`<div class="hand-all-digit joint-sliders"><h4>${name}</h4>${[0,1,2,3].map(j=>slider(f,j,'hq')).join('')}</div>`).join('');
 function selectedSliders(){$('digit-controls').dataset.finger=String(handState.finger);$('digit-controls').innerHTML=[0,1,2,3].map(j=>slider(handState.finger,j,'selected-hq')).join('');}
 const settings=[['hand-load','load'],['hand-pressure','pressureLimit'],['hand-seal','sealForce'],['hand-efficiency','efficiency'],['hand-spring','springPreload'],['hand-spring-rate','springRate'],['hand-line-id','lineID'],['hand-line-length','lineLength'],['hand-viscosity','viscosity'],['hand-bulk','bulk'],['hand-time','closeTime'],['hand-master-bore','masterBore'],['hand-screw-lead','screwLead'],['hand-screw-eff','screwEfficiency']];
 const fmt=(n,d=2)=>Number.isFinite(n)?n.toFixed(d):'—',jointNames=f=>f===0?['MCP','IP']:['MCP','PIP','DIP'];
 function fingerSVG(a){const frames=[],points=[],angles=handState.q[handState.finger].slice(handState.finger===0?2:1),lengths=fingerLengths[handState.finger];let m=mIdentity();
  for(let j=0;j<angles.length;j++){const before=m,after=mMul(m,mRot('y',-angles[j])),c=fingerCylinder(angles[j],j),A=mPoint(before,c.a),B=mPoint(before,c.b),O=mPoint(before,[0,0,0]),end=mPoint(after,[0,0,-lengths[j]]);frames.push({before,after,c,A,B,O,end});points.push(A,B,O,end);m=mMul(after,mTrans(0,0,-lengths[j]));}
  const xs=points.map(p=>-p[2]),ys=points.map(p=>p[0]),minX=Math.min(-20,...xs),maxX=Math.max(...xs),minY=Math.min(-23,...ys),maxY=Math.max(20,...ys),scale=Math.min(590/(maxX-minX),235/(maxY-minY)),map=p=>[55+(-p[2]-minX)*scale,67+(p[0]-minY)*scale],line=(p,q)=>{const A=map(p),B=map(q);return`M${A.join(' ')}L${B.join(' ')}`;};
  let out='<defs><marker id="hf-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#b07e4b"/></marker></defs><text x="25" y="25" fill="#648357" font-size="11">선택 손가락의 굽힘 평면 / 핀 배치는 설계 가정</text>';
  for(let j=0;j<frames.length;j++){const f=frames[j],O=map(f.O),end=map(f.end),body=Math.min(f.c.length-3,f.c.initial-3),G=f.A.map((v,i)=>v+(f.B[i]-v)*body/f.c.length),A=map(f.A),B=map(f.B),g=map(G);out+=`<path d="${line(f.O,f.end)}" stroke="#a3ba98" stroke-width="19" stroke-linecap="round"/>`;
   // Tactile pad segment uses the distal frame, leaving the dorsal cylinder visible.
   const padA=mPoint(f.after,[8,0,-5]),padB=mPoint(f.after,[8,0,-lengths[j]+5]);out+=`<path d="${line(padA,padB)}" stroke="#d6e3b8" stroke-width="8" stroke-linecap="round"/><path d="${line(f.O,f.B)}" stroke="#687f63" stroke-width="5"/><path d="M${A.join(' ')}L${g.join(' ')}" stroke="#6c9fae" stroke-width="11"/><path d="M${g.join(' ')}L${B.join(' ')}" stroke="#b9c9c5" stroke-width="4"/><circle cx="${O[0]}" cy="${O[1]}" r="9" fill="#657f59" stroke="#e7eddc" stroke-width="2"/><circle cx="${O[0]}" cy="${O[1]}" r="13" fill="none" stroke="#b49b58" stroke-width="2" stroke-dasharray="2 2"/><circle cx="${A[0]}" cy="${A[1]}" r="3" fill="#31596b"/><circle cx="${B[0]}" cy="${B[1]}" r="3" fill="#31596b"/><text x="${O[0]-5}" y="${O[1]+31}" fill="#476c39" font-size="11">${jointNames(handState.finger)[j]} ${fmt(angles[j],1)}°</text>`;
  }
  const tip=map(mPoint(m,[0,0,0])),q=angles.reduce((s,v)=>s+v,0)*Math.PI/180,n=[-Math.sin(q),Math.cos(q)];out+=`<path d="M${tip[0]+n[0]*40} ${tip[1]+n[1]*40}L${tip[0]} ${tip[1]}" stroke="#b07e4b" stroke-width="2" marker-end="url(#hf-arrow)"/><text x="${tip[0]+8}" y="${tip[1]-15}" fill="#ab7847" font-size="11">F ${handState.load} N</text><text x="25" y="344" fill="#738864" font-size="11">青: 단동 실린더 / 금색: 복귀 스프링 / 연두: 안쪽 촉각 면</text>`;
  return out.replace('青:','청록:');
 }
 function sectionSVG(row){const h=handState,j=row.joint,ratio=Math.min(1,row.stroke/pinGeometry[j].stroke),piston=280+ratio*62;return`<rect x="25" y="56" width="380" height="102" rx="8" fill="#8da9a4"/><rect x="50" y="77" width="330" height="60" fill="#e4ece1"/><rect x="50" y="77" width="${piston-50}" height="60" fill="#73a9bd"/><rect x="${piston}" y="77" width="13" height="60" fill="#bed0c6"/><rect x="${piston+13}" y="97" width="220" height="20" fill="#b3c4bd"/><rect x="379" y="73" width="16" height="68" fill="#c6d4bf"/><path d="M${piston+3} 77V137M385 97V117" stroke="#a77857" stroke-width="3"/><path d="M10 107H50" stroke="#5896af" stroke-width="9"/><text x="25" y="27" font-size="11" fill="#5c7851">단동 실린더 단면 개념 / 비축척 / ${jointNames(handState.finger)[j]}</text><text x="80" y="112" fill="#ecf4ee" font-size="12">가압실 ${fmt(row.pressure)} MPa</text><text x="430" y="84" fill="#6e8562" font-size="11">로드 Ø${h.rod} / 스트로크 ${fmt(row.stroke)} mm</text><text x="450" y="140" fill="#647b5b" font-size="11">복귀력: 외부 관절 스프링</text><text x="25" y="184" fill="#73876a" font-size="10">보어 Ø${h.bore[j]} / 외경 Ø${h.outer[j]} / 씰·가이드 형상은 후보 예약</text>`;}
 function circuitSVG(row){const boxes=[{x:15,w:90,t:'모터',s:`${fmt(row.motorTorque,3)} N·m`},{x:119,w:94,t:'스크루',s:`리드 ${handState.screwLead} mm`},{x:227,w:120,t:'주실린더',s:`Ø${handState.masterBore} / ${fmt(row.masterReal)} mm`},{x:425,w:111,t:'단동 실린더',s:`${fmt(row.requiredForce,1)} N`},{x:553,w:130,t:'크랭크·관절',s:'스프링 복귀'}];let out='<text x="18" y="24" fill="#617f52" font-size="11">제안 회로 / 실제 제조사 회로 미확인 · 주실린더가 물러나면 스프링이 유체를 되돌림</text>';
  for(const b of boxes)out+=`<rect x="${b.x}" y="97" width="${b.w}" height="65" rx="4" fill="${b.x<350?'#dae6cf':'#cadfdb'}" stroke="#93ad80"/><text x="${b.x+b.w/2}" y="121" text-anchor="middle" fill="#3f6332" font-size="11">${b.t}</text><text x="${b.x+b.w/2}" y="144" text-anchor="middle" fill="#69865a" font-size="10">${b.s}</text>`;
  out+='<path d="M105 130H119M213 130H227M536 130H553" stroke="#869f77" stroke-width="3"/><path d="M347 130H425" stroke="#5c9ab0" stroke-width="6"/><path d="M385 130V62" stroke="#5c9ab0" stroke-width="2"/><circle cx="385" cy="57" r="13" fill="#e9f1e1" stroke="#8caa7a"/><text x="385" y="61" text-anchor="middle" fill="#608052" font-size="11">P</text><text x="410" y="61" fill="#7a8f6c" font-size="10">압력 센서·주입/에어빼기 포트 예약</text>';
  return out+`<text x="250" y="198" fill="#718b63" font-size="11">단일 유압 라인: 내경 Ø${handState.lineID} × ${handState.lineLength} m / 선로 손실 ${fmt(row.loss,3)} MPa</text><text x="22" y="225" fill="#829374" font-size="10">외부 힘이 역방향을 요구하면 단동 실린더는 당기는 힘을 만들지 못합니다.</text>`;
 }
 window.renderHandReview=()=>{
  const h=handState;if($('digit-controls').dataset.finger!==String(h.finger))selectedSliders();$('hand-digit').value=h.finger;for(const[id,key]of settings)$(id).value=h[key];for(let j=0;j<3;j++)$('hand-bore-'+j).value=h.bore[j];$('hand-cover').checked=h.cover;$('hand-ports').checked=h.ports;$('hand-section').checked=h.section;
  for(let f=0;f<5;f++)for(let j=0;j<4;j++)for(const prefix of['hq','selected-hq']){const el=$(prefix+'-'+f+'-'+j);if(el){el.value=h.q[f][j];$(prefix+'-'+f+'-'+j+'-out').textContent=fmt(h.q[f][j],1)+'°';}}
  const a=handFingerAnalysis(),names=jointNames(h.finger);h.driveJoint=Math.min(h.driveJoint,a.rows.length-1);$('hand-drive-joint').innerHTML=names.map((n,j)=>`<option value="${j}">${n}</option>`).join('');$('hand-drive-joint').value=h.driveJoint;const row=a.rows[h.driveJoint],angleMax=range(h.finger,h.finger===0?h.driveJoint+2:h.driveJoint+1)[1],maxCommand=fingerCylinder(angleMax,h.driveJoint).stroke*row.area/(Math.PI*h.masterBore**2/4);$('master-command').max=maxCommand;$('master-command').value=row.masterIdeal;$('master-command-out').textContent=fmt(row.masterIdeal)+' mm';
  $('finger-title').textContent=digitNames[h.finger]+' · 손등 기구와 힘 전달';$('finger-mechanism').innerHTML=fingerSVG(a);$('hand-cylinder-section').innerHTML=sectionSVG(row);const detail=handCylinderDetail(row.angle,h.driveJoint);$('hand-assembly-detail').innerHTML=[['몸체 / 피스톤 중심',fmt(detail.body)+' / '+fmt(detail.piston)+' mm'],['피스톤–가이드 여유',fmt(detail.pistonToGuide)+' mm'],['로드 고정 길이',fmt(detail.rodLength)+' mm'],['튜브 최소 벽 두께',fmt(detail.wall)+' mm'],['검토 상한 압력의 내벽 원주응력',fmt(detail.hoopAtPressureLimit)+' MPa'],['핀 이중 전단 / 부시 평균 면압',fmt(row.requiredForce/(2*Math.PI*3**2/4))+' / '+fmt(row.requiredForce/(2*3*3))+' MPa']].map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join('');$('hand-fluid-circuit').innerHTML=circuitSVG(row);
  const maxP=Math.max(...a.rows.map(r=>r.supply));$('hand-metrics').innerHTML=`<div><span>요구 공급압 최대</span><strong>${fmt(maxP)} MPa</strong></div><div><span>현재 법선 방향 힘 상한 추산</span><strong>${a.capacity===null?'—':fmt(a.capacity,1)+' N'}</strong></div><div><span>14호스 가정 묶음 Ø</span><strong>${fmt(a.bundleDiameter,1)} mm</strong></div>`;
  const issues=a.rows.flatMap((r,j)=>[r.supply>h.pressureLimit?names[j]+' 압력 상한 초과':null,!r.unilateral?names[j]+' 역방향 힘 요구':null,r.lever<=.5?names[j]+' 모멘트암 부족':null,r.stroke>r.capacity?names[j]+' 스트로크 부족':null,r.packingMargin<1?names[j]+' 씰·피스톤 길이 예약 부족':null,!Number.isFinite(r.returnTime)?names[j]+' 스프링 복귀 불가':null]).filter(Boolean);if(a.bundleDiameter>20)issues.push('호스 묶음이 현재 손목 Ø20 예약을 초과');$('hand-assessment').textContent=(issues.length?issues.join(' · '):'현재 후보 기구에서 설정한 정적 압력·스트로크 범위 안입니다.')+' 이 값은 실제 FRIDAY의 파지 성능이나 제조 완료 판정이 아닙니다.';$('hand-assessment').classList.toggle('warn',!!issues.length);
  $('hand-load-table').innerHTML=a.rows.map((r,j)=>`<tr class="${r.within&&Number.isFinite(r.returnTime)?'':'warning'}"><td>${names[j]}<small>${fmt(r.angle,1)}°</small></td><td>${fmt(r.length)} / ${fmt(r.stroke)}<small>몸체 ${fmt(r.bodyLength,1)} / 여유 ${fmt(r.packingMargin,1)}</small></td><td>${fmt(r.lever)}</td><td>${fmt(r.loadTorque,3)} / ${fmt(r.spring,3)}</td><td>${fmt(r.requiredForce,1)}</td><td>${fmt(r.pressure)} / ${fmt(r.supply)}</td><td>${fmt(r.masterIdeal,3)} / ${fmt(r.masterReal,3)}</td><td>${fmt(r.motorTorque,3)}</td><td>${Number.isFinite(r.returnTime)?fmt(r.returnTime,3):'정지/복귀불가'}</td></tr>`).join('');
  const budget=handMassBudget();$('hand-mass-budget').innerHTML=budget.rows.map(([name,m])=>`<tr><td>${name}</td><td>${m}</td></tr>`).join('')+`<tr><td><b>합계 / 목표 배분</b></td><td><b>${budget.total}</b></td></tr>`;
  $('hand-interface-notes').innerHTML=`외경 Ø${h.outer.join(' / ')} mm · 로드 Ø${h.rod} mm · 스트로크 예약 12 / 10 / 7 mm. 몸체는 닫힌 핀간 길이에서 3 mm를 뺀 후보이며, 스트로크 외에 씰·가이드·피스톤 합계 6 mm를 예약해 길이 여유를 검토합니다.<br>세 관절의 크랭크 핀 좌표는 설계 데이터 JSON에 포함합니다. 핀·부시·기계식 스톱·씰 홈·포트 나사와 조립 공차는 제작 도면 확정 전입니다.<br><br>호스 14개 × 외경 Ø${h.lineOD} mm, 포장률 65% → 묶음 Ø${fmt(a.bundleDiameter,1)} mm 추산. 현재 손목 중공 Ø20 mm 예약과 비교하되 피팅 외경·최소 굽힘 반경·케이블을 포함한 통과성은 검증 전입니다.<br><br>최대 Re=${fmt(Math.max(...a.rows.map(r=>r.re)),0)}. 층류식을 사용한 손실 추산이며 실제 유체와 호스의 유효 물성 측정이 필요합니다.`;
  const normalized=h.q.flatMap((q,f)=>q.slice(f===0?2:1).map((v,j)=>v/(f===0?[65,75][j]:fingerLimits[j])));if(Math.max(...normalized)-Math.min(...normalized)>.02)$('hand-grip-out').textContent='개별 설정';
 };
 function refresh(){window.renderMechanismReview();inspector();draw();}
 for(const root of[$('digit-controls'),$('all-hand-controls')])root.addEventListener('input',e=>{const el=e.target;if(el.matches('input[data-finger]')){handState.q[+el.dataset.finger][+el.dataset.joint]=+el.value;refresh();}});
 $('hand-digit').addEventListener('change',()=>{handState.finger=+$('hand-digit').value;handState.driveJoint=0;selectedSliders();refresh();});
 function number(id,set){$(id).addEventListener('input',()=>{const e=$(id),v=+e.value,ok=e.value!==''&&Number.isFinite(v)&&v>=+e.min&&v<=+e.max;e.classList.toggle('error-input',!ok);if(ok){set(v);refresh();}});}
 for(const[id,key]of settings)number(id,v=>{handState[key]=v;if(key==='lineID')handState.lineOD=v+1.5;});for(let j=0;j<3;j++)number('hand-bore-'+j,v=>handState.bore[j]=v);
 for(const[id,key]of[['hand-cover','cover'],['hand-ports','ports'],['hand-section','section']])$(id).addEventListener('change',()=>{handState[key]=$(id).checked;draw();});
 $('hand-drive-joint').addEventListener('change',()=>{handState.driveJoint=+$('hand-drive-joint').value;window.renderHandReview();});
 $('master-command').addEventListener('input',()=>{const j=handState.driveJoint,f=handState.finger,A=Math.PI*handState.bore[j]**2/4,Am=Math.PI*handState.masterBore**2/4,target=+$('master-command').value*Am/A,maxAngle=range(f,f===0?j+2:j+1)[1];handState.q[f][f===0?j+2:j+1]=inverseFingerStroke(target,j,maxAngle);refresh();});
 function handView(back,expand=true){mechanism.scope='hand';partGroup='hand';document.querySelectorAll('[data-group]').forEach(b=>b.classList.toggle('active',b.dataset.group==='hand'));window.renderMechanismReview();select(back?'fingerHydraulic':'tactile');yaw=(back?-1.1:.95)-(beltDesign.enabled?mechanism.angles[4]*Math.PI/180:0);elevation=.45;zoom=1;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');});draw();if(expand&&$('expand-view').getAttribute('aria-pressed')!=='true')$('expand-view').click();$('model').scrollIntoView({block:'center'});}
 $('hand-back-view').addEventListener('click',()=>handView(true));$('hand-palm-view').addEventListener('click',()=>handView(false));document.querySelector('[data-scope="hand"]').addEventListener('click',()=>handView(true,false));
 document.querySelectorAll('[data-hand-pose]').forEach(b=>b.addEventListener('click',()=>{const mode=b.dataset.handPose;if(mode==='review')handState.q=handDefaults.q.map(q=>[...q]);else if(mode==='open')handState.q=handDefaults.q.map((q,f)=>f===0?[10,-25,0,0]:[q[0],0,0,0]);else if(mode==='grasp'){applyHandGrip(.8);handState.q[0][0]=30;handState.q[0][1]=-30;}else handState.q=[[30,-40,45,55],[0,45,60,35],[-2,10,15,10],[3,10,15,10],[7,10,15,10]];refresh();}));
 selectedSliders();mechanism.scope='hand';partGroup='hand';document.querySelectorAll('[data-group]').forEach(b=>b.classList.toggle('active',b.dataset.group==='hand'));window.renderMechanismReview();select('fingerHydraulic');yaw=-1.1;elevation=.45;zoom=1;draw();
})();
